BEGIN;
SELECT plan(13);
UPDATE app.check_in_assignments SET status='cancelled' WHERE patient_id='f1111111-1111-4111-8111-111111111111' AND status='pending';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT api.save_checkin_questions('11111111-1111-4111-8111-111111111111','[{"id":"eeeeeeee-1111-4111-8111-111111111111","text":"¿Cómo te sentís?","type":"scale","enabled":true,"required":true,"archived":false,"options":[],"alert":null}]',NULL);
SELECT lives_ok($$SELECT api.save_checkin_patient_frequency('11111111-1111-4111-8111-111111111111','f1111111-1111-4111-8111-111111111111','daily')$$,'Professional chooses daily cadence');
SELECT ok((SELECT (item->>'configured')::boolean FROM jsonb_array_elements(api.get_checkin_automation('11111111-1111-4111-8111-111111111111')->'patients') item WHERE item->>'patient_id'='f1111111-1111-4111-8111-111111111111'),'Chosen default becomes explicitly configured');
SELECT api.save_checkin_automation_global('11111111-1111-4111-8111-111111111111',true,NULL);
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT is((SELECT assigned FROM api.run_checkin_automation_for_service(current_date)),1,'Daily run assigns one check-in');
SELECT is((SELECT count(*) FROM app.check_in_assignments WHERE patient_id='f1111111-1111-4111-8111-111111111111' AND status='pending'),1::bigint,'Only one pending assignment exists');
UPDATE app.checkin_patient_schedules SET next_run_on=current_date WHERE patient_id='f1111111-1111-4111-8111-111111111111';
SELECT is((SELECT skipped_pending FROM api.run_checkin_automation_for_service(current_date)),1,'Pending assignment skips the cycle');
SELECT is((SELECT count(*) FROM app.check_in_assignments WHERE patient_id='f1111111-1111-4111-8111-111111111111' AND status='pending'),1::bigint,'Skipped cycle does not accumulate assignments');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT lives_ok($$SELECT api.save_checkin_patient_frequency('11111111-1111-4111-8111-111111111111','f1111111-1111-4111-8111-111111111111','weekly')$$,'Professional changes cadence to weekly');
SELECT lives_ok($$SELECT api.save_checkin_patient_frequency('11111111-1111-4111-8111-111111111111','f1111111-1111-4111-8111-111111111111','paused')$$,'Professional pauses one patient');
SELECT is((SELECT item->>'frequency' FROM jsonb_array_elements(api.get_checkin_automation('11111111-1111-4111-8111-111111111111')->'patients') item WHERE item->>'patient_id'='f1111111-1111-4111-8111-111111111111'),'paused','Paused frequency is visible');
SELECT throws_ok($$SELECT api.save_checkin_patient_frequency('22222222-2222-4222-8222-222222222222','f5555555-5555-4555-8555-555555555555','daily')$$,NULL,NULL,'Cross-tenant schedule denied');
SELECT throws_ok($$SELECT * FROM api.run_checkin_automation_for_service(current_date)$$,NULL,NULL,'Authenticated user cannot run scheduler');
SELECT set_config('request.jwt.claims','{"sub":"a1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
SELECT throws_ok($$SELECT api.get_checkin_automation('11111111-1111-4111-8111-111111111111')$$,NULL,NULL,'Platform Admin cannot inspect schedules');
SELECT throws_ok($$SELECT api.save_checkin_automation_global('11111111-1111-4111-8111-111111111111',true,NULL)$$,NULL,NULL,'Platform Admin cannot change automation');
SELECT * FROM finish();
ROLLBACK;
